def f(n, t): 
# Объявляем функцию f с параметрами: n - текущее число, t - список чисел в траектории
    if n < 3: 
    # Если число стало меньше 3, достичь числа 3 невозможно
        return 0 
         # возвращаем 0
    if n == 3 and (9 in t or 16 in t): 
    # Если дошли до 3, но в пути встречались числа 9 или 16
        return 0 
        # Такая программа не подходит - возвращаем 0
    if n == 3: 
    # Если дошли до 3 и запрещённых чисел (9,16) в траектории не было
        return 1 
        # Нашли одну подходящую программу - возвращаем 1
    if n > 3: 
    # Если текущее число больше 3, применяем все три доступные команды
        return f(n-1, t+[n]) + f(n-2, t+[n]) + f(n//3, t+[n]) 
        # Суммируем результаты для команд (это будут 0 - если запуск неудачный, 1 - если запуск удачный)
print(f(19, [])) 
# Запускаем функцию для числа 19 с пустым списком траектории и выводим результат

